WITH valid AS (SELECT *, LOWER(browser) AS browser_lower FROM sessions WHERE browser IS DISTINCT FROM 'Edge' AND customer_id IS NOT NULL), with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) AS prev_started_at FROM valid), with_gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM with_prev), sessions_sessions AS (SELECT id, customer_id, browser, started_at, country, SUM(is_new_session) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, MAX(started_at) AS last_started_at, COUNT(DISTINCT country) AS distinct_countries, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, COUNT(*) FILTER (WHERE browser = 'Safari') AS safari_rows FROM sessions_sessions GROUP BY CASE WHEN burst_id >= 8 THEN 'HIGH' ELSE 'LOW' END;
